use crate::aap::caps::{http_client, notifier};

struct Node;

fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0xF) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment lookup keyed on the digest's text. The result is
        // deliberately not used, so it cannot alter the node's output;
        // a transport failure is returned as a value and ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&composed.overview)
        );
        let _ = http_client::fetch(&url);

        let message = format!(
            "Digest {}: {} entries, {} items considered",
            composed.date,
            composed.entries.len(),
            composed.considered.len()
        );
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
